Object.assign(HINTS,{"lp_udav": ["удав", "крупная неядовитая змея: душит добычу и глотает её целиком."], "lp_bridge": ["бридж", "карточная игра, которую любили взрослые."], "lp_sahara": ["Сахара", "самая большая жаркая пустыня на Земле, на севере Африки."], "lp_aster": ["астероид", "маленькое небесное тело, крошечная «планетка»."], "lp_baobab": ["баобаб", "огромное дерево Африки с очень толстым стволом."], "lp_shirma": ["ширма", "складная перегородка, которая защищает от ветра и чужих глаз."], "lp_kolpak": ["колпак", "стеклянный колокол, которым накрывают растения от холода."], "lp_vulkan": ["вулкан", "гора, из которой вырываются огонь, пепел и раскалённая лава. Потухший вулкан давно не просыпался."], "lp_gorn": ["горностай", "зверёк с белым мехом; горностаем отделывали королевские мантии."], "lp_podd": ["подданный", "житель государства, который подчиняется королю."], "lp_posol": ["посол", "человек, который представляет своего правителя в другой стране."], "lp_chest": ["честолюбец", "человек, который больше всего хочет славы и похвал."], "lp_ugovor": ["уговор", "договорённость, правило, которое обещали соблюдать."], "lp_geogr": ["географ", "учёный, который описывает Землю: моря, горы, реки и города."], "lp_efem": ["эфемерный", "недолговечный, такой, что скоро исчезнет."], "lp_karavan": ["караван", "вереница путников с вьючными животными, идущая через пустыню."], "lp_eho": ["эхо", "звук, который отражается от скал и возвращается обратно."], "lp_pri": ["приручить", "сделать ручным; у Лиса — создать узы, стать нужными друг другу."], "lp_obryad": ["обряд", "обычай, который повторяют в одно и то же время."], "lp_strel": ["стрелочник", "железнодорожник, который переводит стрелки и направляет поезда."], "lp_pil": ["пилюля", "таблетка, лекарство в виде шарика."], "lp_vorot": ["ворот", "вал с ручкой, на который наматывают верёвку колодца."], "lp_bubenec": ["бубенец", "маленький звонкий колокольчик."], "lp_obol": ["оболочка", "то, что покрывает снаружи, как скорлупа или кожура."]});
Object.assign(CARDS,{"lp_hat": {"n": "Рисунок № 1", "m": "1", "d": "Удав, который проглотил слона. Взрослые видят шляпу", "book": "lp"}, "lp_prince": {"n": "Маленький принц", "m": "П", "d": "Мальчик с золотыми волосами с астероида Б-612", "book": "lp"}, "lp_baob": {"n": "Баобаб", "m": "Б", "d": "Росток надо выполоть, пока он не разорвал планету", "book": "lp"}, "lp_box": {"n": "Ящик с барашком", "m": "Я", "d": "Предмет. Три дырочки — чтобы барашку было чем дышать", "book": "lp"}, "lp_rose": {"n": "Роза", "m": "Р", "d": "Единственная во всей Вселенной. Четыре шипа", "book": "lp"}, "lp_king": {"n": "Король", "m": "К", "d": "Отдаёт только разумные приказы", "book": "lp"}, "lp_busi": {"n": "Деловой человек", "m": "Д", "d": "Пятьсот один миллион звёзд — в ящике стола", "book": "lp"}, "lp_lamp": {"n": "Фонарщик", "m": "Ф", "d": "Верен уговору. Тысяча четыреста сорок закатов в сутки", "book": "lp"}, "lp_snake": {"n": "Змея", "m": "З", "d": "Тоньше пальца. Разгадывает все загадки", "book": "lp"}, "lp_fox": {"n": "Лис", "m": "Л", "d": "«Хорошо видит только сердце»", "book": "lp"}, "lp_well": {"n": "Колодец", "m": "В", "d": "Место. Вода, которая как подарок", "book": "lp"}, "lp_bells": {"n": "Смеющиеся звёзды", "m": "★", "d": "Пятьсот миллионов бубенцов", "book": "lp"}, "lp_b612": {"n": "Астероид Б-612", "m": "Б", "d": "Редкая. За финал без ошибок", "rare": true, "book": "lp"}, "lpm1": {"n": "Деревянная корона", "m": "I", "d": "Воспоминание из игры. Её вырезал друг", "book": "lp"}, "lpm2": {"n": "Фонарь для того, кто возвращается", "m": "II", "d": "Воспоминание из игры. Свет зажигали для одного человека", "book": "lp"}, "lpm3": {"n": "Звезда по имени Пуговица", "m": "III", "d": "Воспоминание из игры. Владеть звездой нельзя", "book": "lp"}, "lpm4": {"n": "Колокольчик в траве", "m": "IV", "d": "Воспоминание из игры. Время, отданное другому, не пропадает", "book": "lp"}, "lpm5": {"n": "Роза под стеклом", "m": "V", "d": "Воспоминание из игры. Он отвечает за неё", "book": "lp"}});
